import{_ as e,o as i,c as a,a6 as t,a9 as n}from"./chunks/framework.ZMCvXf1_.js";const g=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md"}'),l={name:"getting-started/installation.md"};function o(r,s,h,d,p,c){return i(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p><img src="'+n+`" alt="Installing noorm: the install script, creating an identity, and bootstrapping a project" loading="lazy"></p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>A supported database: <ul><li>PostgreSQL</li><li>MySQL</li><li>SQLite</li><li>SQL Server (MSSQL)</li></ul></li></ul><h2 id="install-the-cli" tabindex="-1">Install the CLI <a class="header-anchor" href="#install-the-cli" aria-label="Permalink to “Install the CLI”">​</a></h2><p><code>noorm</code> is a non-interactive CLI by default. Every command emits structured output suitable for scripting or piping into CI/CD. Running <code>noorm ui</code> launches the optional Ink/React terminal wizard for when you&#39;d rather point-and-click.</p><h3 id="macos-linux" tabindex="-1">macOS / Linux <a class="header-anchor" href="#macos-linux" aria-label="Permalink to “macOS / Linux”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://noorm.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>This downloads a self-contained binary for your platform. The installer looks for a user-writable bin directory already in your PATH (<code>~/.local/bin</code>, <code>~/bin</code>, etc.) so you don&#39;t need sudo. No runtime dependencies needed.</p><div class="tip custom-block"><p class="custom-block-title">Corporate network?</p><p>If <code>noorm.dev</code> is blocked, use the GitHub mirror:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/noormdev/noorm/master/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div></div><p>You can also override the install location:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NOORM_INSTALL_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">~/my-tools</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://noorm.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><h3 id="npm" tabindex="-1">npm <a class="header-anchor" href="#npm" aria-label="Permalink to “npm”">​</a></h3><p>If you already work in a Node project, npm installs the same binary and puts it on your PATH for you:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @noormdev/cli</span></span></code></pre></div><p>The package is a thin wrapper: installing it downloads the prebuilt binary for your platform and verifies it, exactly as the shell installer does. <code>npx @noormdev/cli</code> works too if you&#39;d rather not install globally.</p><p>This is the most convenient route on Windows, and the one to reach for when you want noorm pinned per-project rather than per-machine.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h3><p>Use the npm install above, or download <a href="https://github.com/noormdev/noorm/releases" target="_blank" rel="noreferrer">noorm-windows-x64.exe</a> from the latest <code>@noormdev/cli</code> release, rename it to <code>noorm.exe</code>, and add it to your PATH.</p><h3 id="integrity-verification" tabindex="-1">Integrity verification <a class="header-anchor" href="#integrity-verification" aria-label="Permalink to “Integrity verification”">​</a></h3><p>Every install path verifies the downloaded binary before it runs. The release publishes a <code>checksums.txt</code> alongside the binaries, and the installer (<code>install.sh</code>), the npm <code>postinstall</code> step, and <code>noorm update</code> each recompute the binary&#39;s SHA-256 and compare it against that file before making the binary executable. A mismatch aborts — a corrupted download or a tampered release asset never gets run.</p><p>Verification is fail-closed: if <code>checksums.txt</code> can&#39;t be fetched (an offline mirror, a network block, an older release without it), the install stops rather than trusting an unverified binary. To override that one case — and only that case — set <code>NOORM_INSECURE=1</code>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NOORM_INSECURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://noorm.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># self-update equivalent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --insecure</span></span></code></pre></div><p><code>NOORM_INSECURE</code> skips verification only when the checksums can&#39;t be reached. A confirmed hash mismatch always fails, escape hatch or not — the flag can&#39;t wave through a binary that has actually been altered.</p><h3 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to “Verify”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h3 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to “Update”">​</a></h3><p>noorm can update itself:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or launch the TUI (\`noorm ui\`) and press [u] from the home screen</span></span></code></pre></div><h2 id="install-the-sdk-optional" tabindex="-1">Install the SDK (Optional) <a class="header-anchor" href="#install-the-sdk-optional" aria-label="Permalink to “Install the SDK (Optional)”">​</a></h2><p>For programmatic access in scripts, tests, or custom tooling:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @noormdev/sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kysely</span></span></code></pre></div><p>The SDK uses peer dependencies. Install the driver for your database:</p><table tabindex="0"><thead><tr><th>Dialect</th><th>Install</th></tr></thead><tbody><tr><td>PostgreSQL</td><td><code>npm install pg</code></td></tr><tr><td>MySQL</td><td><code>npm install mysql2</code></td></tr><tr><td>SQLite</td><td><code>npm install better-sqlite3</code></td></tr><tr><td>SQL Server</td><td><code>npm install tedious tarn</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">CLI Includes Drivers</p><p>The CLI bundles all drivers — no extra installation needed. These are only required if you&#39;re using the SDK directly.</p></div><h2 id="install-the-agent-skill-optional" tabindex="-1">Install the Agent Skill (Optional) <a class="header-anchor" href="#install-the-agent-skill-optional" aria-label="Permalink to “Install the Agent Skill (Optional)”">​</a></h2><p>If you work with an AI coding agent — Claude Code, Codex, Cursor, Gemini CLI — install the noorm skill:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> noormdev/noorm/skills</span></span></code></pre></div><p>Agents otherwise guess at noorm&#39;s conventions, and several of them are non-obvious enough to guess wrong: SDK methods throw named errors rather than returning them, <code>attempt()</code> is used deliberately rather than everywhere, the codebase uses no <code>try</code>/<code>catch</code>, and test helpers carry safety guards that exist for a reason. The skill covers all of it, plus the headless CLI flags used in CI.</p><p>It installs four references the agent reads on demand:</p><table tabindex="0"><thead><tr><th>Reference</th><th>Covers</th></tr></thead><tbody><tr><td><code>sdk.md</code></td><td><code>createContext()</code>, Kysely patterns, error handling, testing</td></tr><tr><td><code>cli.md</code></td><td>Headless commands, flags, exit codes, CI usage</td></tr><tr><td><code>templates.md</code></td><td><code>.sql.tmpl</code> syntax and data loaders</td></tr><tr><td><code>config.md</code></td><td><code>settings.yml</code>, paths, stages, secrets</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Include paths are relative to <code>paths.sql</code></p><p>The single most common mistake — by people and agents alike — is writing <code>build.include</code> entries relative to the project root. They resolve against <code>paths.sql</code>. The skill states this explicitly; <code>noorm run build</code> also warns when an include entry matches nothing.</p></div><h2 id="initialize-a-project" tabindex="-1">Initialize a Project <a class="header-anchor" href="#initialize-a-project" aria-label="Permalink to “Initialize a Project”">​</a></h2><p>Run <code>noorm init</code> in your project root. It prompts for the identity to create (skipped if you already have one) and scaffolds the project:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>The init wizard creates:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>your-project/</span></span>
<span class="line"><span>├── .gitignore                 # gets a .noorm/state/ entry appended</span></span>
<span class="line"><span>├── .noorm/</span></span>
<span class="line"><span>│   ├── .gitignore             # ignores state/</span></span>
<span class="line"><span>│   ├── settings.yml           # Project settings (commit this)</span></span>
<span class="line"><span>│   └── state/</span></span>
<span class="line"><span>│       └── state.enc          # Encrypted state (don&#39;t commit)</span></span>
<span class="line"><span>├── sql/                       # Your SQL files</span></span>
<span class="line"><span>│   └── .gitkeep</span></span>
<span class="line"><span>└── changes/                   # Versioned changes</span></span>
<span class="line"><span>    └── .gitkeep</span></span></code></pre></div><p><code>noorm init</code> is strictly interactive and exits with an error on a non-TTY unless you pass <code>--yes</code> and already have an identity at <code>~/.noorm/identity.{key,pub,json}</code>.</p><p>Adding the first database config comes next, from the TUI (<code>noorm ui</code>, then <code>c</code> for config and <code>a</code> to add).</p><div class="warning custom-block"><p class="custom-block-title">Git Ignore</p><p><code>noorm init</code> adds <code>.noorm/state/</code> to your <code>.gitignore</code> for you. That folder holds encrypted configs and secrets specific to each developer&#39;s machine. The <code>.noorm/settings.yml</code> should be committed — it&#39;s the shared project configuration.</p></div><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><p>You&#39;re ready to go! Continue to:</p><ul><li><a href="/getting-started/first-build.html">First Build</a> - Complete the 5-minute tutorial</li><li><a href="/getting-started/concepts.html">Concepts</a> - Understand the mental model</li></ul>`,53)])])}const u=e(l,[["render",o]]);export{g as __pageData,u as default};
